// Example: {"address":{"city":null,"country_code":"country code","district":null,"line1":"line1","line2":null,"postal_code":null},"created_at":"2026-03-01T09:00:00Z","currency":"currency","fiscal_year_start_month":1,"id":"0192a3f0-1000-7000-8000-000000000002","lock_date":null,"name":"Ali Veli","org_id":"0192a3f0-1000-7000-8000-000000000003","status":"active","timezone":"timezone","updated_at":"2026-03-01T09:00:00Z","version":1}
type Site struct {
	// Address A postal address.
	Address   Address   `json:"address"`
	CreatedAt time.Time `json:"created_at"`

	// Currency ISO 4217; one per site
	Currency string `json:"currency"`

	// FiscalYearStartMonth 1..12, default 1
	FiscalYearStartMonth int64              `json:"fiscal_year_start_month"`
	Id                   openapi_types.UUID `json:"id"`

	// LockDate Postings dated on or before this are rejected (`locked_period`).
	LockDate nullable.Nullable[openapi_types.Date] `json:"lock_date"`
	Name     string                                `json:"name"`
	OrgId    openapi_types.UUID                    `json:"org_id"`

	// Status Open enum.
	Status SiteStatus `json:"status"`

	// Timezone IANA zone
	Timezone  string    `json:"timezone"`
	UpdatedAt time.Time `json:"updated_at"`

	// Version Optimistic-lock counter; send it back as If-Match on updates.
	Version int64 `json:"version"`
}

// SiteStatus Open enum.
type SiteStatus string

